+  keyId: string;
+  iv: string;
+  authTag: string;
+}
+
+export class BlobEncryptionClient {
+  private containerClient: ContainerClient;
+  private keyManager: KeyManager;
+
+  constructor(
+    blobServiceClient: BlobServiceClient,
+    containerName: string,
